INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7526915, 1202935, 185714, '<td valign="top">Congratulations on the Red!<br/> <br/>Great shot!</td>', 'Congratulations on the Red! Great shot!', '2017-08-04 07:39:29.000000', NULL, 0),
(7526918, 1202751, 54446, '<td valign="top">Very fine work!  Congrats on the Blue!</td>', 'Very fine work!  Congrats on the Blue!', '2017-08-04 08:40:11.000000', NULL, 0),
(7527075, 1203009, 59029, '<td valign="top">Greetings from the Critique Club!  Very interesting image here, Marcel, and had to laugh at the comment about it looking like the cover of a self-help book :-)  I do think the way the flower echoes the shape of the hand is very cool, and the colours complement each other well.  In terms of getting across the idea of hands, the hand is competing with the flower. That''s why I think it finished relatively low. You do have quite a bit of chromatic aberration (aka ''purple fringe'' on the right side of the hand, and it looks like the hand texture is overlaid atop the flower, which makes the flower have a skin-like appearance.  Overall not a bad idea, tough to pull off, but at least you had a nice clean hand to work with :-)<br/> <br/>Susan</td>', 'Greetings from the Critique Club!  Very interesting image here, Marcel, and had to laugh at the comment about it looking like the cover of a self-help book :-)  I do think the way the flower echoes the shape of the hand is very cool, and the colours complement each other well.  In terms of getting across the idea of hands, the hand is competing with the flower. That''s why I think it finished relatively low. You do have quite a bit of chromatic aberration (aka ''purple fringe'' on the right side of the hand, and it looks like the hand texture is overlaid atop the flower, which makes the flower have a skin-like appearance.  Overall not a bad idea, tough to pull off, but at least you had a nice clean hand to work with :-) Susan', '2017-08-04 18:40:20.000000', NULL, 0),
(7527173, 1203062, 74588, '<td valign="top">after this most unsuccessful pic. i will take a short break again.<br/>i am sure i wont be missed :)</td>', 'after this most unsuccessful pic. i will take a short break again.i am sure i wont be missed :)', '2017-08-05 12:15:42.000000', NULL, 0),
(7527212, 1203062, 30364, '<td valign="top">You''re always missed Jan, because when you take a break there is a hole here that nobody but you seems able to fill.  So keep it filled, please?  Anyway, how can you say it''s most unsuccessful?  It''s merely finished in the last few places in a popular vote, and here that''s a distinction that frequently means your work is either really bad or really good.  Your stuff is really good much more often than it is really bad.  And it''s <i>never</i> really mediocre.  If it was, your every entry would be celebrated.  And you wouldn''t want that.  If that happened I''d have to tell you to take a short break.</td>', 'You''re always missed Jan, because when you take a break there is a hole here that nobody but you seems able to fill.  So keep it filled, please?  Anyway, how can you say it''s most unsuccessful?  It''s merely finished in the last few places in a popular vote, and here that''s a distinction that frequently means your work is either really bad or really good.  Your stuff is really good much more often than it is really bad.  And it''s never really mediocre.  If it was, your every entry would be celebrated.  And you wouldn''t want that.  If that happened I''d have to tell you to take a short break.', '2017-08-05 16:12:26.000000', NULL, 0),
(7527219, 1202751, 97225, '<td valign="top">Congrats on the blue. Lovely work.</td>', 'Congrats on the blue. Lovely work.', '2017-08-05 19:39:30.000000', NULL, 0),
